 16→export function SecurityTab() {
 17→  const { checkMfaStatus, isMfaEnabled, factorCount, threshold } = useMfa();
 18→  const { logout } = useAuth();
 19→  const [showWizard, setShowWizard] = useState(false);
 20→  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
 21→  const [deleteInput, setDeleteInput] = useState('');
 22→  const [isDeleting, setIsDeleting] = useState(false);
 23→  const [deleteError, setDeleteError] = useState<string | null>(null);
 24→
 25→  // Check MFA status on mount
 26→  useEffect(() => {
 27→    checkMfaStatus();
 28→  }, [checkMfaStatus]);
 29→
 30→  const handleEnrollmentComplete = useCallback(() => {
 31→    setShowWizard(false);
 32→    checkMfaStatus();
 33→  }, [checkMfaStatus]);
 34→
 35→  const handleEnrollmentCancel = useCallback(() => {
 36→    setShowWizard(false);
 37→  }, []);
 38→
 39→  const handleDeleteAccount = useCallback(async () => {
 40→    if (deleteInput !== 'DELETE') return;
 41→    setIsDeleting(true);
 42→    setDeleteError(null);
 43→    try {
 44→      await authApi.deleteAccount();
 45→      // Account deleted server-side. Clear local state and redirect.
 46→      try {
 47→        await logout();
 48→      } catch {
 49→        // Account is already gone — force redirect even if logout cleanup fails
 50→        window.location.href = '/login';
 51→      }
 52→    } catch (err) {
 53→      setDeleteError(err instanceof Error ? err.message : 'Failed to delete account');
 54→    } finally {
 55→      setIsDeleting(false);
 56→    }
 57→  }, [deleteInput, logout]);
 58→
 59→  const handleCancelDelete = useCallback(() => {
 60→    setShowDeleteConfirm(false);
 61→    setDeleteInput('');
 62→    setDeleteError(null);
 63→  }, []);
 64→
 65→  return (
 66→    <div className="security-tab">
 67→      {/* MFA Status Badge */}
