120→
121→          {/* Recovery Phrase section (only when MFA enabled) */}
122→          {isMfaEnabled && (
123→            <div className="security-tab-section">
124→              <h3 className="security-tab-section-title">{'// recovery phrase'}</h3>
125→              <RecoveryPhraseSection />
126→            </div>
127→          )}
128→        </>
129→      )}
130→
131→      {/* Danger Zone */}
132→      <div className="security-tab-danger-zone">
133→        <h3 className="security-tab-danger-zone-title">{'// danger_zone'}</h3>
134→        {!showDeleteConfirm ? (
135→          <div className="security-tab-danger-zone-content">
136→            <p className="security-tab-danger-zone-desc">
137→              permanently delete your account and all associated data. this action cannot be undone.
138→            </p>
139→            <button
140→              type="button"
141→              className="security-tab-danger-btn"
142→              onClick={() => setShowDeleteConfirm(true)}
143→            >
144→              --delete-account
145→            </button>
146→          </div>
147→        ) : (
148→          <div className="security-tab-danger-zone-confirm">
149→            <p className="security-tab-danger-zone-warn">
150→              this will permanently delete your account, vault, files, shares, and all encryption
151→              keys. type <strong>DELETE</strong> to confirm.
152→            </p>
153→            <input
154→              type="text"
155→              className="security-tab-danger-input"
156→              aria-label="Type DELETE to confirm account deletion"
157→              value={deleteInput}
158→              onChange={(e) => setDeleteInput(e.target.value)}
159→              placeholder="type DELETE to confirm"
160→              autoComplete="off"
161→              spellCheck={false}
162→              disabled={isDeleting}
163→            />
164→            {deleteError && <p className="security-tab-danger-error">{deleteError}</p>}
165→            <div className="security-tab-danger-actions">
166→              <button
167→                type="button"
