125→   */
126→  async getWalletConnectors(): Promise<string[]> {
127→    await this.walletConnectorList.waitFor({ state: 'visible', timeout: 5000 });
128→    const options = this.page.locator('.wallet-connector-option');
129→    const count = await options.count();
130→    const names: string[] = [];
