183→                  role="checkbox"
184→                  aria-checked={acknowledged}
185→                  tabIndex={0}
186→                  onClick={toggleAcknowledged}
187→                  onKeyDown={handleCheckboxKeyDown}
188→                  data-testid="mfa-wizard-acknowledge"
189→                >
190→                  <span className="mfa-wizard-checkbox-box" aria-hidden="true">
191→                    {acknowledged ? '[x]' : '[ ]'}
192→                  </span>
193→                  <span className="mfa-wizard-checkbox-label">
194→                    I have written down and safely stored my recovery phrase
195→                  </span>
196→                </div>
197→              </>
198→            )}
199→          </div>
200→
201→          <div className="mfa-wizard-actions">
202→            <button
