208→              --back
209→            </button>
210→            <button
211→              type="button"
212→              className="mfa-wizard-btn mfa-wizard-btn-primary"
213→              onClick={handleGoToStep3}
214→              disabled={!acknowledged || isLoading || !!error}
215→              data-testid="mfa-wizard-continue"
216→            >
217→              --continue
218→            </button>
219→          </div>
220→        </div>
221→      )}
222→
223→      {/* Step 3: Success */}
224→      {step === 3 && (
225→        <div className="mfa-wizard-step" data-testid="mfa-wizard-step-3">
226→          <h3 className="mfa-wizard-step-title">{'// mfa enabled'}</h3>
227→          <div className="mfa-wizard-step-content">
228→            <div className="mfa-wizard-success">
229→              <span className="mfa-wizard-success-icon" aria-hidden="true">
230→                [OK]
231→              </span>
232→              <p className="mfa-wizard-text">
