  1→import { useCallback } from 'react';
  2→import BN from 'bn.js';
  3→import * as secp256k1 from '@noble/secp256k1';
  4→import { hexToBytes, bytesToHex } from '@cipherbox/crypto';
  5→import { useCoreKit } from './core-kit-provider';
  6→import { COREKIT_STATUS } from './core-kit';
  7→import { authApi } from '../api/auth';
  8→
  9→export type CoreKitLoginResult = 'logged_in' | 'required_share';
 10→
 11→export function useCoreKitAuth() {
 12→  const { coreKit, status, isLoggedIn, isInitialized, isRequiredShare, syncStatus } = useCoreKit();
 13→
 14→  /**
 15→   * Login with Google: Backend verifies Google idToken, issues CipherBox JWT,
 16→   * then we call loginWithJWT on Core Kit.
 17→   */
 18→  const loginWithGoogle = useCallback(
 19→    async (
 20→      googleIdToken: string
 21→    ): Promise<{
 22→      cipherboxJwt: string;
 23→      email?: string;
 24→      userId: string;
 25→      status: CoreKitLoginResult;
 26→    }> => {
 27→      if (!coreKit) throw new Error('Core Kit not initialized');
 28→
 29→      const { idToken: cipherboxJwt, userId, email } = await authApi.identityGoogle(googleIdToken);
 30→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 31→      return { cipherboxJwt, email, userId, status: coreKitStatus };
 32→    },
 33→    [coreKit, syncStatus]
 34→  );
 35→
 36→  /**
 37→   * Login with Email: Backend handles OTP send/verify, issues CipherBox JWT.
 38→   */
 39→  const loginWithEmailOtp = useCallback(
 40→    async (
 41→      email: string,
 42→      otp: string
 43→    ): Promise<{ cipherboxJwt: string; userId: string; status: CoreKitLoginResult }> => {
 44→      if (!coreKit) throw new Error('Core Kit not initialized');
 45→
 46→      const { idToken: cipherboxJwt, userId } = await authApi.identityEmailVerify(email, otp);
 47→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 48→      return { cipherboxJwt, userId, status: coreKitStatus };
 49→    },
 50→    [coreKit, syncStatus]
 51→  );
 52→
 53→  /**
 54→   * Login with Wallet: Backend verifies SIWE signature, issues CipherBox JWT,
 55→   * then we call loginWithJWT on Core Kit.
 56→   */
 57→  const loginWithWallet = useCallback(
 58→    async (
 59→      cipherboxJwt: string,
 60→      userId: string
 61→    ): Promise<{ cipherboxJwt: string; userId: string; status: CoreKitLoginResult }> => {
 62→      if (!coreKit) throw new Error('Core Kit not initialized');
 63→
 64→      const coreKitStatus = await doLoginWithCoreKit(coreKit, syncStatus, cipherboxJwt, userId);
 65→      return { cipherboxJwt, userId, status: coreKitStatus };
 66→    },
 67→    [coreKit, syncStatus]
 68→  );
 69→
 70→  /**
 71→   * Get vault keypair from Core Kit's exported TSS key.
 72→   */
 73→  const getVaultKeypair = useCallback(async (): Promise<{
 74→    publicKey: Uint8Array;
 75→    privateKey: Uint8Array;
 76→  } | null> => {
 77→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
 78→
 79→    try {
 80→      console.log('[CoreKit] _UNSAFE_exportTssKey starting...');
 81→      console.time('[CoreKit] exportTssKey');
 82→      const privateKeyHex = await coreKit._UNSAFE_exportTssKey();
 83→      console.timeEnd('[CoreKit] exportTssKey');
 84→      console.log('[CoreKit] exportTssKey done, hex length:', privateKeyHex.length);
 85→      const privKeyHex = privateKeyHex.startsWith('0x') ? privateKeyHex.slice(2) : privateKeyHex;
 86→      const privateKey = hexToBytes(privKeyHex);
 87→      const publicKey = secp256k1.getPublicKey(privateKey, false); // uncompressed (65 bytes)
 88→      console.log('[CoreKit] keypair derived, pubkey hex length:', publicKey.length * 2);
 89→      return { publicKey, privateKey };
 90→    } catch (err) {
 91→      console.timeEnd('[CoreKit] exportTssKey');
 92→      console.error('[CoreKit] Failed to export TSS key:', err);
 93→      return null;
 94→    }
 95→  }, [coreKit]);
 96→
 97→  /**
 98→   * Get uncompressed public key hex for backend auth.
 99→   */
100→  const getPublicKeyHex = useCallback(async (): Promise<string | null> => {
101→    const keypair = await getVaultKeypair();
102→    if (!keypair) return null;
103→    return bytesToHex(keypair.publicKey);
104→  }, [getVaultKeypair]);
105→
106→  /**
107→   * Logout from Core Kit.
108→   */
109→  const logout = useCallback(async (): Promise<void> => {
110→    if (!coreKit) return;
111→    try {
112→      if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
113→        await coreKit.logout();
114→      }
115→    } catch (err) {
116→      console.error('[CoreKit] Logout error:', err);
117→    } finally {
118→      syncStatus();
119→    }
120→  }, [coreKit, syncStatus]);
121→
122→  return {
123→    status,
124→    isLoggedIn,
125→    isInitialized,
126→    isRequiredShare,
127→    loginWithGoogle,
128→    loginWithEmailOtp,
129→    loginWithWallet,
130→    getVaultKeypair,
131→    getPublicKeyHex,
132→    logout,
133→  };
134→}
