  1→import { useCallback, useEffect, useState } from 'react';
  2→import { useMfa } from '../../hooks/useMfa';
  3→import { RecoveryPhraseGrid } from './RecoveryPhraseGrid';
  4→
  5→type MfaEnrollmentWizardProps = {
  6→  onComplete: () => void;
  7→  onCancel: () => void;
  8→};
  9→
 10→type WizardStep = 1 | 2 | 3;
 11→
 12→/**
 13→ * Step-by-step MFA enrollment wizard.
 14→ *
 15→ * Step 1: Explain what MFA does and that it cannot be undone.
 16→ * Step 2: Enable MFA, display recovery phrase, require acknowledgment.
 17→ * Step 3: Confirmation that MFA is enabled with factor count.
 18→ */
 19→export function MfaEnrollmentWizard({ onComplete, onCancel }: MfaEnrollmentWizardProps) {
 20→  const { enableMfa, checkMfaStatus, factorCount, threshold } = useMfa();
 21→
 22→  const [step, setStep] = useState<WizardStep>(1);
 23→  const [isLoading, setIsLoading] = useState(false);
 24→  const [error, setError] = useState<string | null>(null);
 25→  const [mnemonic, setMnemonic] = useState<string[]>([]);
 26→  const [partiallyEnabled, setPartiallyEnabled] = useState(false);
 27→  const [acknowledged, setAcknowledged] = useState(false);
 28→
 29→  const handleEnableMfa = useCallback(async () => {
 30→    setIsLoading(true);
 31→    setError(null);
 32→    try {
 33→      const phrase = await enableMfa();
 34→      setMnemonic(phrase.split(' '));
 35→      setIsLoading(false);
 36→    } catch (err) {
 37→      setIsLoading(false);
 38→      // If MFA was partially enabled (server succeeded but post-check failed),
 39→      // guide user to recovery instead of a broken retry loop
 40→      const mfaStatus = checkMfaStatus();
 41→      if (mfaStatus.isMfaEnabled) {
 42→        setPartiallyEnabled(true);
 43→        setError(
 44→          'MFA was enabled but an error occurred. Please close this dialog and use ' +
 45→            '"Regenerate Recovery Phrase" in Settings > Security to obtain your recovery phrase.'
 46→        );
 47→      } else {
 48→        setError(err instanceof Error ? err.message : 'Failed to enable MFA');
 49→      }
 50→    }
 51→  }, [enableMfa, checkMfaStatus]);
 52→
 53→  const handleGoToStep2 = useCallback(() => {
 54→    setStep(2);
 55→    if (mnemonic.length === 0) {
 56→      handleEnableMfa();
 57→    }
 58→  }, [handleEnableMfa, mnemonic.length]);
 59→
 60→  const handleGoToStep3 = useCallback(() => {
 61→    setMnemonic([]);
 62→    setStep(3);
 63→  }, []);
 64→
 65→  const handleGoBackToStep1 = useCallback(() => {
 66→    // Don't clear mnemonic -- if user goes back to step 1 and forward again,
 67→    // we skip re-calling enableMfa() to avoid generating a different phrase.
 68→    setStep(1);
 69→  }, []);
 70→
 71→  // Clear mnemonic from memory on unmount
 72→  useEffect(() => () => setMnemonic([]), []);
 73→
 74→  const toggleAcknowledged = useCallback(() => {
 75→    setAcknowledged((prev) => !prev);
 76→  }, []);
 77→
 78→  const handleCheckboxKeyDown = useCallback(
 79→    (e: React.KeyboardEvent) => {
 80→      if (e.key === 'Enter' || e.key === ' ') {
 81→        e.preventDefault();
 82→        toggleAcknowledged();
 83→      }
 84→    },
 85→    [toggleAcknowledged]
 86→  );
 87→
 88→  return (
 89→    <div className="mfa-wizard" data-testid="mfa-wizard">
 90→      {/* Step indicator */}
 91→      <div className="mfa-wizard-step-indicator">
 92→        <span className="mfa-wizard-step-label">{'step ' + step + ' of 3'}</span>
 93→        <div className="mfa-wizard-progress-bar">
 94→          <div className={`mfa-wizard-progress-segment ${step >= 1 ? 'complete' : ''}`} />
 95→          <div className={`mfa-wizard-progress-segment ${step >= 2 ? 'complete' : ''}`} />
 96→          <div className={`mfa-wizard-progress-segment ${step >= 3 ? 'complete' : ''}`} />
 97→        </div>
 98→      </div>
 99→
100→      {/* Step 1: Explain MFA */}
101→      {step === 1 && (
102→        <div className="mfa-wizard-step" data-testid="mfa-wizard-step-1">
103→          <h3 className="mfa-wizard-step-title">{'// enable multi-factor authentication'}</h3>
104→          <div className="mfa-wizard-step-content">
105→            <p className="mfa-wizard-text">
106→              MFA adds an extra layer of security to your vault. When enabled, logging in from a new
107→              device will require approval from an existing device or your recovery phrase.
108→            </p>
109→            <p className="mfa-wizard-text">
110→              Known devices will continue to log in seamlessly -- MFA only challenges new or unknown
111→              devices.
112→            </p>
113→            <div className="mfa-wizard-warning-box">
114→              <p className="mfa-wizard-warning-text">
115→                Enabling MFA is permanent and cannot be undone. You can manage individual factors
116→                (devices, recovery phrase) after enrollment, but MFA itself stays active.
117→              </p>
118→            </div>
119→          </div>
120→          <div className="mfa-wizard-actions">
121→            <button
122→              type="button"
123→              className="mfa-wizard-btn mfa-wizard-btn-secondary"
124→              onClick={onCancel}
125→              data-testid="mfa-wizard-cancel"
126→            >
127→              --cancel
128→            </button>
129→            <button
130→              type="button"
131→              className="mfa-wizard-btn mfa-wizard-btn-primary"
132→              onClick={handleGoToStep2}
133→              data-testid="mfa-wizard-continue"
134→            >
135→              --continue
136→            </button>
137→          </div>
138→        </div>
139→      )}
140→
141→      {/* Step 2: Recovery Phrase */}
142→      {step === 2 && (
143→        <div className="mfa-wizard-step" data-testid="mfa-wizard-step-2">
144→          <h3 className="mfa-wizard-step-title">{'// recovery phrase'}</h3>
145→          <div className="mfa-wizard-step-content">
146→            {isLoading && (
147→              <div className="mfa-wizard-loading" data-testid="mfa-wizard-loading">
148→                <span className="mfa-wizard-spinner" aria-hidden="true" />
149→                enabling MFA and generating recovery phrase...
150→              </div>
151→            )}
152→
153→            {error && (
154→              <div className="mfa-wizard-error" role="alert" data-testid="mfa-wizard-error">
155→                <p>{error}</p>
156→                {!partiallyEnabled && (
157→                  <button
158→                    type="button"
159→                    className="mfa-wizard-btn mfa-wizard-btn-secondary"
160→                    onClick={handleEnableMfa}
161→                  >
162→                    --retry
163→                  </button>
164→                )}
165→              </div>
166→            )}
167→
168→            {!isLoading && !error && mnemonic.length > 0 && (
169→              <>
170→                <p className="mfa-wizard-text">
171→                  Write down these 24 words in order and store them in a safe place. This is the
172→                  only way to recover your vault if you lose all your devices.
173→                </p>
174→
175→                <RecoveryPhraseGrid words={mnemonic} />
176→
177→                <div className="mfa-wizard-danger-box" role="alert">
178→                  If you lose this phrase and all your devices, your account CANNOT be recovered.
179→                </div>
180→
181→                <div
182→                  className={`mfa-wizard-checkbox ${acknowledged ? 'checked' : ''}`}
183→                  role="checkbox"
184→                  aria-checked={acknowledged}
185→                  tabIndex={0}
186→                  onClick={toggleAcknowledged}
187→                  onKeyDown={handleCheckboxKeyDown}
188→                  data-testid="mfa-wizard-acknowledge"
189→                >
190→                  <span className="mfa-wizard-checkbox-box" aria-hidden="true">
191→                    {acknowledged ? '[x]' : '[ ]'}
192→                  </span>
193→                  <span className="mfa-wizard-checkbox-label">
194→                    I have written down and safely stored my recovery phrase
195→                  </span>
196→                </div>
197→              </>
198→            )}
199→          </div>
200→
201→          <div className="mfa-wizard-actions">
202→            <button
203→              type="button"
204→              className="mfa-wizard-btn mfa-wizard-btn-secondary"
205→              onClick={handleGoBackToStep1}
206→              data-testid="mfa-wizard-back"
207→            >
208→              --back
209→            </button>
210→            <button
211→              type="button"
212→              className="mfa-wizard-btn mfa-wizard-btn-primary"
213→              onClick={handleGoToStep3}
214→              disabled={!acknowledged || isLoading || !!error}
215→              data-testid="mfa-wizard-continue"
216→            >
217→              --continue
218→            </button>
219→          </div>
220→        </div>
221→      )}
222→
223→      {/* Step 3: Success */}
224→      {step === 3 && (
225→        <div className="mfa-wizard-step" data-testid="mfa-wizard-step-3">
226→          <h3 className="mfa-wizard-step-title">{'// mfa enabled'}</h3>
227→          <div className="mfa-wizard-step-content">
228→            <div className="mfa-wizard-success">
229→              <span className="mfa-wizard-success-icon" aria-hidden="true">
230→                [OK]
231→              </span>
232→              <p className="mfa-wizard-text">
233→                Multi-factor authentication has been successfully enabled on your account.
234→              </p>
235→            </div>
236→            <div className="mfa-wizard-factor-summary">
237→              <span className="mfa-wizard-factor-count">
238→                {factorCount} factors active, {threshold}/{factorCount} threshold
239→              </span>
240→            </div>
241→            <p className="mfa-wizard-text mfa-wizard-text-dim">
242→              New devices will require approval from an existing device or your recovery phrase. You
243→              can manage your factors from Settings &gt; Security at any time.
244→            </p>
245→          </div>
246→          <div className="mfa-wizard-actions">
247→            <button
248→              type="button"
249→              className="mfa-wizard-btn mfa-wizard-btn-primary"
250→              onClick={onComplete}
251→              data-testid="mfa-wizard-done"
252→            >
253→              --done
254→            </button>
255→          </div>
256→        </div>
257→      )}
258→    </div>
259→  );
260→}
