// ──────────────────────────────────────────────────
// TC-MFA-01: Wallet login and MFA enrollment
// ──────────────────────────────────────────────────
test('TC-MFA-01: wallet login and MFA enrollment', async () => {
  test.setTimeout(120_000); // Core Kit init + enableMFA can be slow

  // Debug: track console messages and URL changes during the test
  const consoleMessages: string[] = [];
  const urlChanges: string[] = [];
  primaryPage.on('console', (msg) => {
    consoleMessages.push(`[${msg.type()}] ${msg.text()}`);
  });
  primaryPage.on('framenavigated', (frame) => {
    if (frame === primaryPage.mainFrame()) {
      urlChanges.push(frame.url());
    }
  });

  // 1. Login via wallet (happy path — no MFA yet, fresh identity)
  const result = await loginViaWallet(primaryPage, { timeout: 60_000 });
  expect(result.outcome).toBe('success');

  // 2. Navigate to Settings → Security tab
  await navigateToSecurityTab(primaryPage);

  // 3. Verify MFA is currently disabled
  const statusBefore = await getMfaStatusText(primaryPage);
  expect(statusBefore).toBe('[DISABLED]');

  // 4. Run through the enrollment wizard
  //    This calls enableMFA on Devnet (~10-15s), generates recovery phrase,
  //    requires acknowledge checkbox, and confirms success.
  try {
    recoveryPhrase = await enrollMfa(primaryPage, { enableTimeout: 60_000 });
  } catch (err) {
    // Dump diagnostics on failure
    const currentUrl = primaryPage.url();
    console.error('enrollMfa failed. Diagnostics:');
    console.error('  Current URL:', currentUrl);
    console.error('  URL changes:', urlChanges);
    console.error('  Console errors:', consoleErrors.slice(-10));
    // Check if wizard is still visible
    const wizardVisible = await primaryPage.locator('[data-testid="mfa-wizard"]').isVisible().catch(() => false);
    const loadingVisible = await primaryPage.locator('[data-testid="mfa-wizard-loading"]').isVisible().catch(() => false);
    const errorVisible = await primaryPage.locator('[data-testid="mfa-wizard-error"]').isVisible().catch(() => false);
    const errorText = errorVisible ? await primaryPage.locator('[data-testid="mfa-wizard-error"]').textContent() : null;
    console.error('  Wizard visible:', wizardVisible);
    console.error('  Loading visible:', loadingVisible);
    console.error('  Error visible:', errorVisible, errorText);
    throw err;
  }

  // 5. Verify we got a valid 24-word phrase
  const words = recoveryPhrase.split(' ');
  expect(words).toHaveLength(24);
  expect(words.every((w) => w.length > 0)).toBe(true);

  // 6. Verify MFA is now enabled in the Security tab
  const statusAfter = await getMfaStatusText(primaryPage);
  expect(statusAfter).toBe('[ENABLED]');

