// 2. Navigate to Settings → Security tab
await navigateToSecurityTab(primaryPage);

// 3. Verify MFA is currently disabled
const statusBefore = await getMfaStatusText(primaryPage);
expect(statusBefore).toBe('[DISABLED]');

// 4. Inject navigation interceptor to capture any unexpected redirects.
//    Patches history.pushState/replaceState to log call stacks via console.error.
await primaryPage.evaluate(() => {
  const origPushState = history.pushState.bind(history);
  history.pushState = function (...args: Parameters<typeof origPushState>) {
    const url = String(args[2] ?? '');
    if (url.includes('/files')) {
      console.error(`[NAV_TRAP] pushState to ${url}\n${new Error().stack}`);
    }
    return origPushState(...args);
  };
  const origReplaceState = history.replaceState.bind(history);
  history.replaceState = function (...args: Parameters<typeof origReplaceState>) {
    const url = String(args[2] ?? '');
    if (url.includes('/files')) {
      console.error(`[NAV_TRAP] replaceState to ${url}\n${new Error().stack}`);
    }
    return origReplaceState(...args);
  };
  window.addEventListener('hashchange', (e) => {
    if (e.newURL.includes('/files')) {
      console.error(`[NAV_TRAP] hashchange: ${e.oldURL} → ${e.newURL}\n${new Error().stack}`);
    }
  });
});

// Capture NAV_TRAP messages from console
const navTraps: string[] = [];
primaryPage.on('console', (msg) => {
  const text = msg.text();
  if (text.includes('[NAV_TRAP]')) {
    navTraps.push(text);
  }
});

// 5. Run through the enrollment wizard
//    This calls enableMFA on Devnet (~10-15s), generates recovery phrase,
//    requires acknowledge checkbox, and confirms success.
try {
  recoveryPhrase = await enrollMfa(primaryPage, { enableTimeout: 60_000 });
} catch (err) {
  // Dump navigation trap data on failure
  console.error('enrollMfa failed. Navigation traps captured:');
  for (const trap of navTraps) {
    console.error(trap);
  }
  console.error('Current URL:', primaryPage.url());
  throw err;
}

