  // 3. Verify MFA is currently disabled
  const statusBefore = await getMfaStatusText(primaryPage);
  expect(statusBefore).toBe('[DISABLED]');

  // 4. Inject navigation interceptor to capture ALL pushState calls with timing.
  const navTraps: string[] = [];
  primaryPage.on('console', (msg) => {
    const text = msg.text();
    if (text.includes('[NAV_TRAP]')) {
      navTraps.push(text);
    }
  });
  await primaryPage.evaluate(() => {
    let navCount = 0;
    const origPushState = history.pushState.bind(history);
    history.pushState = function (...args: Parameters<typeof origPushState>) {
      navCount++;
      const url = String(args[2] ?? '');
      console.error(`[NAV_TRAP] #${navCount} pushState to ${url} (from: ${window.location.hash})\n${new Error().stack}`);
      return origPushState(...args);
    };
  });

  // 5. Run through the enrollment wizard
  //    This calls enableMFA on Devnet (~10-15s), generates recovery phrase,
  //    requires acknowledge checkbox, and confirms success.
  try {
    recoveryPhrase = await enrollMfa(primaryPage, { enableTimeout: 60_000 });
  } catch (err) {
    // Dump ALL navigation events on failure
    console.error(`enrollMfa failed. ${navTraps.length} navigation(s) captured:`);
    for (const trap of navTraps) {
      console.error(trap);
    }
    console.error('Current URL:', primaryPage.url());
    throw err;
  }

  // 5. Verify we got a valid 24-word phrase
  const words = recoveryPhrase.split(' ');
  expect(words).toHaveLength(24);
  expect(words.every((w) => w.length > 0)).toBe(true);

  // 6. Verify MFA is now enabled in the Security tab
  const statusAfter = await getMfaStatusText(primaryPage);
  expect(statusAfter).toBe('[ENABLED]');
});

// ──────────────────────────────────────────────────
// TC-MFA-02: MFA status reflected in Security tab

