  1→/**
  2→ * Device Info Detection
  3→ *
  4→ * Auto-detects device metadata from the browser environment.
  5→ * Used to populate the device entry when registering in the
  6→ * encrypted device registry.
  7→ */
  8→
  9→import { bytesToHex, CRYPTO_VERSION, type DevicePlatform } from '@cipherbox/crypto';
 10→
 11→/**
 12→ * Auto-detect device information from the browser environment.
 13→ *
 14→ * Returns platform-appropriate metadata for the device registry entry.
 15→ * Device name and model are kept simple -- users can rename in Settings.
 16→ *
 17→ * @returns Device metadata for registry registration
 18→ */
 19→export function detectDeviceInfo(): {
 20→  name: string;
 21→  platform: DevicePlatform;
 22→  appVersion: string;
 23→  deviceModel: string;
 24→} {
 25→  const ua = navigator.userAgent;
 26→
 27→  // Detect platform
 28→  const platform = detectPlatform(ua);
 29→
 30→  // Detect browser name
 31→  const browserName = detectBrowser(ua);
 32→
 33→  // Detect OS name + version
 34→  const osInfo = detectOS(ua);
 35→
 36→  // Device name: "Chrome on macOS" style
 37→  const name = `${browserName} on ${osInfo.name}`;
 38→
 39→  // Device model: "Chrome 123 on macOS 15.2" style
 40→  const deviceModel = `${browserName} on ${osInfo.name}${osInfo.version ? ` ${osInfo.version}` : ''}`;
 41→
 42→  // App version: prefer VITE_APP_VERSION env var, fall back to CRYPTO_VERSION
 43→  const appVersion = import.meta.env.VITE_APP_VERSION || CRYPTO_VERSION;
 44→
 45→  return { name, platform, appVersion, deviceModel };
 46→}
 47→
 48→/**
 49→ * Detect the platform from the user agent string.
 50→ */
 51→function detectPlatform(ua: string): DevicePlatform {
 52→  if (/Macintosh|Mac OS X/i.test(ua)) return 'macos';
 53→  if (/Windows/i.test(ua)) return 'windows';
 54→  if (/Linux/i.test(ua)) return 'linux';
 55→  return 'web';
 56→}
 57→
 58→/**
 59→ * Detect the browser name from the user agent string.
 60→ */
 61→function detectBrowser(ua: string): string {
 62→  // Order matters -- check more specific browsers first
 63→  if (/Edg\//i.test(ua)) return 'Edge';
 64→  if (/OPR\//i.test(ua) || /Opera/i.test(ua)) return 'Opera';
 65→  if (/Firefox\//i.test(ua)) return 'Firefox';
 66→  if (/Chrome\//i.test(ua)) return 'Chrome';
 67→  if (/Safari\//i.test(ua)) return 'Safari';
 68→  return 'Browser';
 69→}
 70→
 71→/**
 72→ * Detect OS name and version from the user agent string.
 73→ */
 74→function detectOS(ua: string): { name: string; version: string } {
 75→  // macOS
 76→  const macMatch = ua.match(/Mac OS X (\d+[._]\d+(?:[._]\d+)?)/);
 77→  if (macMatch) {
 78→    return { name: 'macOS', version: macMatch[1].replace(/_/g, '.') };
 79→  }
 80→
 81→  // Windows
 82→  const winMatch = ua.match(/Windows NT (\d+\.\d+)/);
 83→  if (winMatch) {
 84→    const ntVersionMap: Record<string, string> = {
 85→      '10.0': '10/11',
 86→      '6.3': '8.1',
 87→      '6.2': '8',
 88→      '6.1': '7',
 89→    };
 90→    const friendlyVersion = ntVersionMap[winMatch[1]] || winMatch[1];
 91→    return { name: 'Windows', version: friendlyVersion };
 92→  }
 93→
 94→  // Linux
 95→  if (/Linux/i.test(ua)) {
 96→    return { name: 'Linux', version: '' };
 97→  }
 98→
 99→  return { name: 'Unknown OS', version: '' };
100→}
101→
102→/**
103→ * Compute a privacy-preserving hash of an IP address.
104→ *
105→ * The actual IP is obtained from the backend; this function
106→ * hashes it locally before storing in the registry.
107→ *
