test('TC-MFA-03: device approval - approve', async ({ browser }) => {
  test.setTimeout(120_000);

  // 1. Ensure primary page is on /files (approver device, polls for requests)
  await primaryPage.evaluate(() => {
    window.location.hash = '#/files';
  });
  await primaryPage.waitForURL('**/files', { timeout: 15_000 });

  // 2. Create new context B (no localStorage = new device, same wallet identity)
  const { context: contextB, page: pageB } = await createWalletContext(browser, account);

  try {
    // DIAGNOSTIC: Capture device-approval API calls from context B
    const apiCalls: { url: string; status: number; body?: string }[] = [];
    pageB.on('response', async (response) => {
      if (response.url().includes('device-approval')) {
        let body: string | undefined;
        try { body = await response.text(); } catch { /* stream consumed */ }
        apiCalls.push({ url: response.url(), status: response.status(), body });
      }
    });

    // 3. Login via wallet on context B → should enter REQUIRED_SHARE
    const resultB = await loginViaWallet(pageB, { timeout: 60_000 });
    expect(resultB.outcome).toBe('requiredShare');

    // 4. Wait for DeviceWaitingScreen on context B
    await expect(pageB.locator('[data-testid="device-waiting"]')).toBeVisible({ timeout: 10_000 });

    // DIAGNOSTIC: Wait a moment for the approval request to fire, then log results
    await pageB.waitForTimeout(5_000);
    console.log('[DIAG] device-approval API calls from context B:', JSON.stringify(apiCalls, null, 2));

    // Also check if primary page's MFA is detected as enabled
    const primaryMfaState = await primaryPage.evaluate(() => {
      // Access Zustand store state directly
      const mfaStore = (window as any).__ZUSTAND_MFA_STORE__;
      return { mfaStore: mfaStore ? 'exists' : 'not found' };
