 1→import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
 2→import { IsString, IsNotEmpty, IsIn, Matches } from 'class-validator';
 3→
 4→export type LoginType = 'corekit';
 5→
 6→export class LoginDto {
 7→  @ApiProperty({
 8→    description: 'CipherBox-issued JWT identity token',
 9→    example: 'eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9...',
10→  })
11→  @IsString()
12→  @IsNotEmpty()
13→  idToken!: string;
14→
15→  @ApiProperty({
16→    description:
17→      'secp256k1 public key exported from Core Kit after loginWithJWT (uncompressed, 130 hex chars)',
18→    example: '04abc123...',
19→  })
20→  @IsString()
21→  @IsNotEmpty()
22→  @Matches(/^04[0-9a-fA-F]{128}$/, {
23→    message:
24→      'publicKey must be an uncompressed secp256k1 public key (130 hex chars starting with 04)',
25→  })
26→  publicKey!: string;
27→
28→  @ApiProperty({
29→    description: 'Type of login used (always corekit)',
30→    enum: ['corekit'],
31→    example: 'corekit',
32→  })
33→  @IsString()
34→  @IsIn(['corekit'])
35→  loginType!: LoginType;
36→}
37→
38→export class LoginResponseDto {
39→  @ApiProperty({
40→    description: 'JWT access token for API requests',
41→    example: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...',
42→  })
43→  accessToken!: string;
44→
45→  @ApiProperty({
46→    description: 'Whether this is a new user registration',
47→    example: false,
48→  })
49→  isNewUser!: boolean;
50→
51→  @ApiPropertyOptional({
52→    description:
53→      'Refresh token (only present for desktop clients using X-Client-Type: desktop header)',
54→    example: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...',
55→  })
56→  refreshToken?: string;
57→}
58→
59→// Internal type for service layer (includes refreshToken for cookie)
60→export type LoginServiceResult = {
61→  accessToken: string;
62→  refreshToken: string;
63→  isNewUser: boolean;
64→};
65→

  1→import {
  2→  Inject,
  3→  Injectable,
  4→  Logger,
  5→  UnauthorizedException,
  6→  BadRequestException,
  7→  ForbiddenException,
  8→  OnModuleDestroy,
  9→} from '@nestjs/common';
 10→import { InjectRepository } from '@nestjs/typeorm';
 11→import { ConfigService } from '@nestjs/config';
 12→import { Repository, IsNull, Like, Not } from 'typeorm';
 13→import { createECDH, createHash, timingSafeEqual } from 'crypto';
 14→import * as jose from 'jose';
 15→import * as argon2 from 'argon2';
 16→import Redis from 'ioredis';
 17→import { User } from './entities/user.entity';
 18→import { AuthMethod } from './entities/auth-method.entity';
 19→import { RefreshToken } from './entities/refresh-token.entity';
 20→import { PinnedCid } from '../vault/entities/pinned-cid.entity';
 21→import { IPFS_PROVIDER, IpfsProvider } from '../ipfs/providers/ipfs-provider.interface';
 22→import { JwtIssuerService } from './services/jwt-issuer.service';
 23→import { TokenService } from './services/token.service';
 24→import { SiweService } from './services/siwe.service';
 25→import { parseSiweMessage } from 'viem/siwe';
 26→import { LoginDto, LoginServiceResult } from './dto/login.dto';
 27→import { RefreshServiceResult, LogoutResponseDto } from './dto/token.dto';
 28→import { LinkMethodDto, AuthMethodResponseDto } from './dto/link-method.dto';
 29→
 30→@Injectable()
 31→export class AuthService implements OnModuleDestroy {
 32→  private readonly logger = new Logger(AuthService.name);
 33→  private readonly redis: Redis;
 34→
 35→  constructor(
 36→    private configService: ConfigService,
 37→    private jwtIssuerService: JwtIssuerService,
 38→    private tokenService: TokenService,
 39→    private siweService: SiweService,
 40→    @InjectRepository(User)
 41→    private userRepository: Repository<User>,
 42→    @InjectRepository(AuthMethod)
 43→    private authMethodRepository: Repository<AuthMethod>,
 44→    @InjectRepository(RefreshToken)
 45→    private refreshTokenRepository: Repository<RefreshToken>,
 46→    @InjectRepository(PinnedCid)
 47→    private pinnedCidRepository: Repository<PinnedCid>,
 48→    @Inject(IPFS_PROVIDER)
 49→    private ipfsProvider: IpfsProvider
 50→  ) {
 51→    this.redis = new Redis({
 52→      host: configService.get('REDIS_HOST', 'localhost'),
 53→      port: configService.get<number>('REDIS_PORT', 6379),
 54→      password: configService.get('REDIS_PASSWORD', undefined),
 55→      lazyConnect: true,
 56→    });
 57→  }
 58→
 59→  async onModuleDestroy(): Promise<void> {
 60→    await this.redis.quit();
 61→  }
 62→
 63→  async login(loginDto: LoginDto): Promise<LoginServiceResult> {
 64→    // 1. Verify CipherBox-issued JWT.
 65→    // All auth methods now go through: CipherBox identity provider -> Core Kit loginWithJWT -> /auth/login.
 66→    const payload = await this.verifyCipherBoxJwt(loginDto.idToken);
 67→
 68→    // 2. Find or create user
 69→    let user = await this.userRepository.findOne({
 70→      where: { publicKey: loginDto.publicKey },
 71→    });
 72→
 73→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 74→    // When a user first authenticates via CipherBox identity provider,
 75→    // they get a placeholder publicKey ('pending-core-kit-{userId}').
 76→    // After Core Kit login, the client calls /auth/login with the REAL publicKey.
 77→    // We need to find the placeholder user and update their publicKey.
 78→    if (!user) {
 79→      const verifierId = payload.verifierId || payload.sub;
 80→      if (verifierId) {
 81→        const placeholderUser = await this.userRepository.findOne({
 82→          where: { publicKey: Like(`pending-core-kit-${verifierId}%`) },
 83→        });
 84→        if (placeholderUser) {
 85→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 86→          placeholderUser.publicKey = loginDto.publicKey;
 87→          user = await this.userRepository.save(placeholderUser);
 88→        }
 89→      }
 90→    }
 91→
 92→    const isNewUser = !user;
 93→    if (!user) {
 94→      user = await this.userRepository.save({
 95→        publicKey: loginDto.publicKey,
 96→      });
 97→    }
 98→
 99→    // 3. Find or create auth method
100→    // The identity controller already created the auth method
101→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
102→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
103→    let authMethod: AuthMethod | null;
104→
105→    const identifier = payload.email || payload.sub;
106→    if (!identifier) {
107→      this.logger.warn('CipherBox JWT missing both email and sub claims');
108→      throw new UnauthorizedException('Invalid identity token: missing identifier');
109→    }
110→    const identifierHash = this.siweService.hashIdentifier(identifier);
111→    authMethod = await this.authMethodRepository.findOne({
112→      where: { userId: user.id, identifierHash },
113→    });
114→    if (!authMethod) {
115→      // Fallback: find any auth method for this user (identity controller should have created one)
116→      authMethod = await this.authMethodRepository.findOne({
117→        where: { userId: user.id },
118→      });
119→    }
120→    if (!authMethod) {
121→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
122→      // All logins go through loginType='corekit' now, but infer type from identifier format
123→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
124→      const display =
125→        inferredType === 'wallet'
126→          ? this.siweService.truncateWalletAddress(identifier)
127→          : this.siweService.truncateEmail(identifier);
128→      authMethod = await this.authMethodRepository.save({
129→        userId: user.id,
130→        type: inferredType,
131→        identifier: identifierHash,
132→        identifierHash,
133→        identifierDisplay: display,
134→      });
135→    }
136→
137→    // 4. Update last used timestamp
138→    authMethod.lastUsedAt = new Date();
139→    await this.authMethodRepository.save(authMethod);
140→
141→    // 5. Create tokens
142→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
143→
144→    return {
145→      accessToken: tokens.accessToken,
146→      refreshToken: tokens.refreshToken,
147→      isNewUser,
148→    };
149→  }
