298→  /**
299→   * Get all linked auth methods for a user.
300→   * Returns identifierDisplay (human-readable) for all method types.
301→   * Falls back to identifier if identifierDisplay is not set.
302→   */
303→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
304→    const methods = await this.authMethodRepository.find({
305→      where: { userId },
306→      order: { createdAt: 'ASC' },
307→    });
308→
309→    return methods.map((method) => ({
310→      id: method.id,
311→      type: method.type,
312→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
313→      identifier: method.identifierDisplay || '[redacted]',
314→      lastUsedAt: method.lastUsedAt,
315→      createdAt: method.createdAt,
316→    }));
317→  }
318→
319→  /**
320→   * Link a new auth method to an existing user account.
321→   *
322→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
323→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
324→   *
325→   * Cross-account collision: if the auth method already belongs to a different user,
326→   * a BadRequestException is thrown (user must unlink from the other account first).
327→   */
328→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
329→    // 1. Get the user
330→    const user = await this.userRepository.findOne({ where: { id: userId } });
331→    if (!user) {
332→      throw new UnauthorizedException('User not found');
333→    }
334→
335→    const authMethodType = linkDto.loginType;
336→
337→    if (authMethodType === 'wallet') {
338→      // Wallet linking: verify SIWE message + signature
339→      return this.linkWalletMethod(userId, linkDto);
340→    }
341→
342→    // Google/email linking: verify CipherBox-issued JWT
343→    return this.linkJwtMethod(userId, linkDto);
344→  }
345→
346→  /**
347→   * Link a Google or email auth method via CipherBox JWT verification.
348→   */
349→  private async linkJwtMethod(
350→    userId: string,
351→    linkDto: LinkMethodDto
352→  ): Promise<AuthMethodResponseDto[]> {
353→    // 1. Verify the CipherBox-issued JWT
354→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
355→
356→    // 2. Determine type and identifier, hash for lookup
357→    const authMethodType = linkDto.loginType;
358→    const identifier = payload.email || payload.sub;
359→    if (!identifier) {
360→      throw new BadRequestException('Cannot determine identifier from JWT');
361→    }
362→    const identifierHash = this.siweService.hashIdentifier(identifier);
363→
364→    // 3. Check cross-account collision: same identifier linked to a different user
365→    const crossAccountMethod = await this.authMethodRepository.findOne({
366→      where: {
367→        type: authMethodType,
368→        identifierHash,
369→        userId: Not(userId),
370→      },
371→    });
372→
373→    if (crossAccountMethod) {
374→      throw new BadRequestException(
375→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
376→      );
377→    }
378→
379→    // 4. Check if this exact method is already linked to this user
380→    const existingMethod = await this.authMethodRepository.findOne({
381→      where: {
382→        userId,
383→        type: authMethodType,
384→        identifierHash,
385→      },
386→    });
387→
388→    if (existingMethod) {
389→      throw new BadRequestException('This auth method is already linked to your account');
390→    }
391→
392→    // 5. Create new AuthMethod entity with hashed identifier
393→    await this.authMethodRepository.save({
394→      userId,
395→      type: authMethodType,
396→      identifier: identifierHash,
397→      identifierHash,
398→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
399→      lastUsedAt: new Date(),
400→    });
401→
402→    // 6. Return updated list of methods
403→    return this.getLinkedMethods(userId);
404→  }
405→
406→  /**
407→   * Link a wallet auth method via SIWE verification.
408→   */
409→  private async linkWalletMethod(
410→    userId: string,
411→    linkDto: LinkMethodDto
412→  ): Promise<AuthMethodResponseDto[]> {
413→    // 1. Validate required SIWE fields
414→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
415→      throw new BadRequestException(
416→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
417→      );
418→    }
419→
420→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
421→    const parsed = parseSiweMessage(linkDto.siweMessage);
422→    if (!parsed.nonce) {
423→      throw new BadRequestException('Invalid SIWE message: missing nonce');
424→    }
425→
426→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
427→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
428→    let nonceDeleted: number;
429→    try {
430→      nonceDeleted = await this.redis.del(nonceKey);
431→    } catch (err) {
432→      this.logger.error('Redis error during nonce consumption', err);
433→      throw new BadRequestException('Nonce verification failed');
434→    }
435→    if (!nonceDeleted) {
436→      throw new BadRequestException('Invalid or expired nonce');
437→    }
438→
439→    const walletAddress = await this.siweService.verifySiweMessage(
440→      linkDto.siweMessage,
441→      linkDto.siweSignature as `0x${string}`,
442→      parsed.nonce
443→    );
444→
445→    // 3. Hash the wallet address for lookup
446→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
447→
448→    // 4. Check cross-account collision: same wallet linked to a different user
449→    const crossAccountMethod = await this.authMethodRepository.findOne({
450→      where: {
451→        type: 'wallet',
452→        identifierHash: addressHash,
453→        userId: Not(userId),
454→      },
455→    });
456→
457→    if (crossAccountMethod) {
458→      throw new BadRequestException('This wallet is already linked to another account');
459→    }
460→
461→    // 5. Check if this wallet is already linked to this user
462→    const existingMethod = await this.authMethodRepository.findOne({
463→      where: {
464→        userId,
465→        type: 'wallet',
466→        identifierHash: addressHash,
467→      },
468→    });
469→
470→    if (existingMethod) {
471→      throw new BadRequestException('This wallet is already linked to your account');
472→    }
473→
474→    // 6. Create wallet auth method with hash + truncated display
475→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
476→    await this.authMethodRepository.save({
477→      userId,
478→      type: 'wallet',
479→      identifier: addressHash,
480→      identifierHash: addressHash,
481→      identifierDisplay: truncated,
482→      lastUsedAt: new Date(),
483→    });
484→
485→    // 7. Return updated list of methods
486→    return this.getLinkedMethods(userId);
487→  }
488→
489→  /**
490→   * Unlink an auth method from a user account.
491→   * Cannot unlink the last remaining auth method.
492→   */
493→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
494→    await this.authMethodRepository.manager.transaction(async (manager) => {
495→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
496→      const methods = await manager
497→        .createQueryBuilder(AuthMethod, 'am')
498→        .setLock('pessimistic_write')
499→        .where('am.userId = :userId', { userId })
500→        .getMany();
501→
502→      // 2. Find the target method
503→      const method = methods.find((m) => m.id === methodId);
504→      if (!method) {
505→        throw new BadRequestException('Auth method not found');
506→      }
507→
508→      // 3. Cannot unlink if only 1 method remains
509→      if (methods.length <= 1) {
510→        throw new BadRequestException('Cannot unlink your last auth method');
511→      }
512→
513→      // 4. Delete the method
514→      await manager.remove(method);
515→    });
516→  }
