518→  /**
519→   * Test-only login that bypasses Core Kit entirely.
520→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
521→   *
522→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
523→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
524→   */
525→  async testLogin(
526→    email: string,
527→    secret: string
528→  ): Promise<{
529→    accessToken: string;
530→    refreshToken: string;
531→    isNewUser: boolean;
532→    publicKeyHex: string;
533→    privateKeyHex: string;
534→  }> {
535→    // 1. Defense-in-depth: never allow in production regardless of env var
536→    const nodeEnv = this.configService.get<string>('NODE_ENV');
537→    if (nodeEnv === 'production') {
538→      throw new ForbiddenException('Test login is not available in production');
539→    }
540→
541→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
542→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
543→    if (!expectedSecret) {
544→      throw new ForbiddenException('Test login is not enabled');
545→    }
546→    const secretBuf = Buffer.from(secret);
547→    const expectedBuf = Buffer.from(expectedSecret);
548→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
549→      throw new UnauthorizedException('Invalid test login secret');
550→    }
551→
552→    // 2. Generate deterministic secp256k1 keypair from email
553→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
554→
555→    // 3. Find or create user by email (hash-based lookup)
556→    const normalizedEmail = email.toLowerCase().trim();
557→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
558→
559→    const existingMethod = await this.authMethodRepository.findOne({
560→      where: { type: 'email', identifierHash },
561→      relations: ['user'],
562→    });
563→
564→    let user: User;
565→    let isNewUser = false;
566→
567→    if (existingMethod) {
568→      user = existingMethod.user;
569→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
570→      if (user.publicKey !== publicKeyHex) {
571→        user.publicKey = publicKeyHex;
572→        await this.userRepository.save(user);
573→      }
574→      existingMethod.lastUsedAt = new Date();
575→      await this.authMethodRepository.save(existingMethod);
576→    } else {
577→      isNewUser = true;
578→      user = await this.userRepository.save({ publicKey: publicKeyHex });
579→      await this.authMethodRepository.save({
580→        userId: user.id,
581→        type: 'email',
582→        identifier: identifierHash,
583→        identifierHash,
584→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
585→        lastUsedAt: new Date(),
586→      });
587→    }
588→
589→    // 4. Issue tokens
590→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
591→
592→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
593→
594→    return {
595→      accessToken: tokens.accessToken,
596→      refreshToken: tokens.refreshToken,
597→      isNewUser,
598→      publicKeyHex,
599→      privateKeyHex,
600→    };
601→  }
602→
603→  /**
604→   * Generate a deterministic secp256k1 keypair from an email address.
605→   * Same email always produces the same keypair, enabling consistent
606→   * vault encryption across test runs.
607→   */
608→  private generateDeterministicKeypair(email: string): {
609→    publicKeyHex: string;
610→    privateKeyHex: string;
611→  } {
612→    // Derive 32-byte private key from email via SHA-256
613→    const seed = createHash('sha256')
614→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
615→      .digest();
616→
617→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
618→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
619→    let keyInt = BigInt('0x' + seed.toString('hex'));
620→    keyInt = (keyInt % (n - 1n)) + 1n;
621→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
622→
623→    const ecdh = createECDH('secp256k1');
624→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
625→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
626→
627→    return { publicKeyHex, privateKeyHex };
628→  }
629→}
