136→/**
137→ * Shared Core Kit login logic extracted as a standalone function
138→ * (not a hook method) to avoid re-creation on every render.
139→ *
140→ * Takes a CipherBox JWT and userId, calls loginWithJWT and commitChanges.
141→ * Returns 'logged_in' if device factor found, 'required_share' if MFA
142→ * is enabled but this device lacks a factor.
143→ */
144→async function doLoginWithCoreKit(
145→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
146→  coreKit: any,
147→  syncStatus: () => void,
148→  cipherboxJwt: string,
149→  userId: string
150→): Promise<CoreKitLoginResult> {
151→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
152→  const loginParams: any = {
153→    verifier: 'cipherbox-identity',
154→    verifierId: userId,
155→    idToken: cipherboxJwt,
156→  };
157→
158→  console.log('[CoreKit] loginWithJWT starting...', {
159→    verifier: loginParams.verifier,
160→    verifierId: userId,
161→  });
162→  console.time('[CoreKit] loginWithJWT');
163→  try {
164→    await coreKit.loginWithJWT(loginParams);
165→    console.timeEnd('[CoreKit] loginWithJWT');
166→    console.log('[CoreKit] loginWithJWT completed, status:', coreKit.status);
167→  } catch (err) {
168→    console.timeEnd('[CoreKit] loginWithJWT');
169→    console.error('[CoreKit] loginWithJWT FAILED:', err);
170→    throw err;
171→  }
172→
173→  // Handle status
174→  if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
175→    console.log('[CoreKit] commitChanges starting...');
176→    console.time('[CoreKit] commitChanges');
177→    try {
178→      await coreKit.commitChanges();
179→      console.timeEnd('[CoreKit] commitChanges');
180→      console.log('[CoreKit] commitChanges done');
181→    } catch (err) {
182→      console.timeEnd('[CoreKit] commitChanges');
183→      console.error('[CoreKit] commitChanges FAILED:', err);
184→    }
185→
186→    // DEBUG: Test exportTssKey in isolation BEFORE triggering React updates
187→    console.log('[CoreKit] DEBUG: testing exportTssKey in isolation...');
188→    console.time('[CoreKit] exportTssKey-test');
189→    try {
190→      const testKey = await coreKit._UNSAFE_exportTssKey();
191→      console.timeEnd('[CoreKit] exportTssKey-test');
192→      console.log('[CoreKit] exportTssKey-test succeeded, length:', testKey.length);
193→    } catch (err) {
194→      console.timeEnd('[CoreKit] exportTssKey-test');
195→      console.error('[CoreKit] exportTssKey-test FAILED:', err);
196→    }
197→
198→    console.log('[CoreKit] calling syncStatus...');
199→    syncStatus();
200→    console.log('[CoreKit] syncStatus called, returning logged_in');
201→    return 'logged_in';
202→  }
203→
204→  if (coreKit.status === COREKIT_STATUS.REQUIRED_SHARE) {
205→    // Bug fix: Web3Auth's handleExistingUser() does NOT auto-check localStorage
206→    // for the device factor when the hashedShare has been deleted (post-MFA).
207→    // We must manually retrieve and input the device factor if it exists.
208→    console.log('[CoreKit] REQUIRED_SHARE — checking for device factor in localStorage...');
209→    try {
210→      const deviceFactorHex = await coreKit.getDeviceFactor();
211→      if (deviceFactorHex) {
212→        console.log('[CoreKit] Device factor found in localStorage, auto-inputting...');
213→        await coreKit.inputFactorKey(new BN(deviceFactorHex, 'hex'));
214→
215→        if (coreKit.status === COREKIT_STATUS.LOGGED_IN) {
216→          console.log('[CoreKit] Device factor accepted — now LOGGED_IN');
217→          try {
218→            await coreKit.commitChanges();
219→          } catch (err) {
220→            console.error('[CoreKit] commitChanges after device factor FAILED:', err);
221→          }
222→          syncStatus();
223→          return 'logged_in';
224→        }
225→      } else {
226→        console.log('[CoreKit] No device factor in localStorage — true REQUIRED_SHARE');
227→      }
228→    } catch (err) {
229→      console.warn('[CoreKit] Device factor check failed (expected on new device):', err);
230→    }
231→
232→    syncStatus();
233→    return 'required_share';
234→  }
235→
236→  throw new Error(`Unexpected Core Kit status: ${coreKit.status}`);
237→}
