  try {
    // DIAGNOSTIC: Capture device-approval API calls from context B
    const apiCalls: { url: string; status: number; body?: string }[] = [];
    pageB.on('response', async (response) => {
      if (response.url().includes('device-approval')) {
        let body: string | undefined;
        try { body = await response.text(); } catch { /* stream consumed */ }
        apiCalls.push({ url: response.url(), status: response.status(), body });
