406→  /**
407→   * Link a wallet auth method via SIWE verification.
408→   */
409→  private async linkWalletMethod(
410→    userId: string,
411→    linkDto: LinkMethodDto
412→  ): Promise<AuthMethodResponseDto[]> {
413→    // 1. Validate required SIWE fields
414→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
415→      throw new BadRequestException(
416→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
417→      );
418→    }
419→
420→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
421→    const parsed = parseSiweMessage(linkDto.siweMessage);
422→    if (!parsed.nonce) {
423→      throw new BadRequestException('Invalid SIWE message: missing nonce');
424→    }
425→
426→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
427→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
428→    let nonceDeleted: number;
429→    try {
430→      nonceDeleted = await this.redis.del(nonceKey);
431→    } catch (err) {
432→      this.logger.error('Redis error during nonce consumption', err);
433→      throw new BadRequestException('Nonce verification failed');
434→    }
435→    if (!nonceDeleted) {
436→      throw new BadRequestException('Invalid or expired nonce');
437→    }
438→
439→    const walletAddress = await this.siweService.verifySiweMessage(
440→      linkDto.siweMessage,
441→      linkDto.siweSignature as `0x${string}`,
442→      parsed.nonce
443→    );
444→
445→    // 3. Hash the wallet address for lookup
446→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
447→
448→    // 4. Check cross-account collision: same wallet linked to a different user
449→    const crossAccountMethod = await this.authMethodRepository.findOne({
450→      where: {
451→        type: 'wallet',
452→        identifierHash: addressHash,
453→        userId: Not(userId),
454→      },
455→    });
456→
457→    if (crossAccountMethod) {
458→      throw new BadRequestException('This wallet is already linked to another account');
459→    }
460→
461→    // 5. Check if this wallet is already linked to this user
462→    const existingMethod = await this.authMethodRepository.findOne({
463→      where: {
464→        userId,
465→        type: 'wallet',
466→        identifierHash: addressHash,
467→      },
468→    });
469→
470→    if (existingMethod) {
471→      throw new BadRequestException('This wallet is already linked to your account');
472→    }
473→
474→    // 6. Create wallet auth method with hash + truncated display
475→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
476→    await this.authMethodRepository.save({
477→      userId,
478→      type: 'wallet',
479→      identifier: addressHash,
480→      identifierHash: addressHash,
481→      identifierDisplay: truncated,
482→      lastUsedAt: new Date(),
483→    });
484→
485→    // 7. Return updated list of methods
486→    return this.getLinkedMethods(userId);
487→  }
488→
489→  /**
490→   * Unlink an auth method from a user account.
491→   * Cannot unlink the last remaining auth method.
492→   */
493→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
494→    await this.authMethodRepository.manager.transaction(async (manager) => {
495→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
496→      const methods = await manager
497→        .createQueryBuilder(AuthMethod, 'am')
498→        .setLock('pessimistic_write')
499→        .where('am.userId = :userId', { userId })
500→        .getMany();
501→
502→      // 2. Find the target method
503→      const method = methods.find((m) => m.id === methodId);
504→      if (!method) {
505→        throw new BadRequestException('Auth method not found');
506→      }
507→
508→      // 3. Cannot unlink if only 1 method remains
509→      if (methods.length <= 1) {
510→        throw new BadRequestException('Cannot unlink your last auth method');
511→      }
512→
513→      // 4. Delete the method
514→      await manager.remove(method);
515→    });
516→  }
517→
518→  /**
519→   * Test-only login that bypasses Core Kit entirely.
520→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
521→   *
522→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
523→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
524→   */
525→  async testLogin(
526→    email: string,
527→    secret: string
528→  ): Promise<{
529→    accessToken: string;
530→    refreshToken: string;
531→    isNewUser: boolean;
532→    publicKeyHex: string;
533→    privateKeyHex: string;
534→  }> {
535→    // 1. Defense-in-depth: never allow in production regardless of env var
536→    const nodeEnv = this.configService.get<string>('NODE_ENV');
537→    if (nodeEnv === 'production') {
538→      throw new ForbiddenException('Test login is not available in production');
539→    }
540→
541→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
542→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
543→    if (!expectedSecret) {
544→      throw new ForbiddenException('Test login is not enabled');
545→    }
546→    const secretBuf = Buffer.from(secret);
547→    const expectedBuf = Buffer.from(expectedSecret);
548→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
549→      throw new UnauthorizedException('Invalid test login secret');
550→    }
551→
552→    // 2. Generate deterministic secp256k1 keypair from email
553→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
554→
555→    // 3. Find or create user by email (hash-based lookup)
556→    const normalizedEmail = email.toLowerCase().trim();
557→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
558→
559→    const existingMethod = await this.authMethodRepository.findOne({
560→      where: { type: 'email', identifierHash },
561→      relations: ['user'],
562→    });
563→
564→    let user: User;
565→    let isNewUser = false;
566→
567→    if (existingMethod) {
568→      user = existingMethod.user;
569→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
570→      if (user.publicKey !== publicKeyHex) {
571→        user.publicKey = publicKeyHex;
572→        await this.userRepository.save(user);
573→      }
574→      existingMethod.lastUsedAt = new Date();
575→      await this.authMethodRepository.save(existingMethod);
576→    } else {
577→      isNewUser = true;
578→      user = await this.userRepository.save({ publicKey: publicKeyHex });
579→      await this.authMethodRepository.save({
580→        userId: user.id,
581→        type: 'email',
582→        identifier: identifierHash,
583→        identifierHash,
584→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
585→        lastUsedAt: new Date(),
586→      });
587→    }
588→
589→    // 4. Issue tokens
590→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
591→
592→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
593→
594→    return {
595→      accessToken: tokens.accessToken,
596→      refreshToken: tokens.refreshToken,
597→      isNewUser,
598→      publicKeyHex,
599→      privateKeyHex,
600→    };
601→  }
602→
603→  /**
604→   * Generate a deterministic secp256k1 keypair from an email address.
605→   * Same email always produces the same keypair, enabling consistent
606→   * vault encryption across test runs.
607→   */
608→  private generateDeterministicKeypair(email: string): {
609→    publicKeyHex: string;
610→    privateKeyHex: string;
611→  } {
612→    // Derive 32-byte private key from email via SHA-256
613→    const seed = createHash('sha256')
614→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
615→      .digest();
616→
617→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
618→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
619→    let keyInt = BigInt('0x' + seed.toString('hex'));
620→    keyInt = (keyInt % (n - 1n)) + 1n;
621→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
622→
623→    const ecdh = createECDH('secp256k1');
624→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
625→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
626→
627→    return { publicKeyHex, privateKeyHex };
628→  }
629→}
